    // Get the index of the current character in the alphabet
    $alphabet_index = strpos($alphabet, $message[$i]);
    // If the current character is not in the alphabet, add it to the decrypted message as is
    if ($alphabet_index === false) {
      $decrypted_message .= $message[$i];
    }
    // Otherwise, apply the Caesar cipher decryption formula
    else {
      $decrypted_alphabet_index = ($alphabet_index - $key_value + $max_key_value) % $max_key_value;
      $decrypted_message .= $alphabet[$decrypted_alphabet_index];
    }
  }
  // Add the decrypted message and its key to the array
  $decrypted_messages[$key_value] = $decrypted_message;
}
// Sort the decrypted messages by the number of English words they contain
arsort($decrypted_messages);
// Loop through the decrypted messages and output the one with the most English words
foreach ($decrypted_messages as $key => $decrypted_message) {
  $english_word_count = 0;
  $words = explode(" ", $decrypted_message);
