  { id: 1, name: 'John', purchases: [{ product: 'A', price: 10 }, { product: 'B', price: 15 }] },
  { id: 2, name: 'Jane', purchases: [{ product: 'A', price: 10 }, { product: 'C', price: 20 }] },
