Sure, here's a C# code that generates all possible variations of the given sequence and outputs the total number of variations:
```
using System;
using System.Collections.Generic;
class Program
{
    static void Main(string[] args)
    {
        List<char> sequence = new List<char> { 'C', 'E', 'E', 'E', 'T', 'U', 'U', 'P', 'S', 'S', 'S' };
        List<List<char>> variations = GenerateVariations(sequence);
        Console.WriteLine("Total number of variations: " + variations.Count);
        foreach (List<char> variation in variations)
        {
            Console.WriteLine(string.Join("", variation));
        }
    }
    static List<List<char>> GenerateVariations(List<char> sequence)
    {
        List<List<char>> variations = new List<List<char>>();
        if (sequence.Count == 0)
        {
            variations.Add(new List<char>());
            return variations;
        }
        char first = sequence[0];
        List<char> rest = sequence.GetRange(1, sequence.Count - 1);
        List<List<char>> subVariations = GenerateVariations(rest);
        foreach (List<char> subVariation in subVariations)
        {
            for (int i = 0; i <= subVariation.Count; i++)
            {
                List<char> variation = new List<char>(subVariation);
                variation.Insert(i, first);
                if (!variations.Contains(variation))
                {
                    variations.Add(variation);
                }
            }
        }
        return variations;
    }
}
```
The `GenerateVariations` method recursively generates all possible variations of the given sequence by taking the first character, generating all possible variations of the rest of the sequence, and inserting the first character at every possible position in each variation of the rest of the sequence.
The `Main` method creates the initial sequence, generates all possible variations using the `GenerateVariations` method, outputs the total number of variations, and then outputs each variation.

