```go
package main
import (
    "fmt"
)
func main() {
    var input string
    fmt.Print("Enter a string: ")
    fmt.Scanln(&input)
    // convert string to rune slice
    runes := []rune(input)
    // use one loop to swap first and last runes, then second and second-to-last runes, etc.
    for i := 0; i < len(runes)/2; i++ {
        runes[i], runes[len(runes)-1-i] = runes[len(runes)-1-i], runes[i]
    }
    // convert rune slice back to string
    output := string(runes)
    fmt.Println("Reversed string:", output)
}
```
Explanation:
