Yes, you can use Go's built-in `net/http` and `html` packages to extract the desired information from the HTML page. Here's a code snippet that should do the job:
```go
package main
import (
    "fmt"
    "log"
    "net/http"
    "strconv"
    "strings"
    "golang.org/x/net/html"
)
func main() {
    // Make a GET request to the URL of the HTML page
    res, err := http.Get("https://en.wikipedia.org/wiki/List_of_English_monarchs")
    if err != nil {
        log.Fatal(err)
    }
    defer res.Body.Close()
    // Parse the HTML page
    doc, err := html.Parse(res.Body)
    if err != nil {
        log.Fatal(err)
    }
    // Traverse the HTML tree to find the table containing the monarchs
    monarchTable := findMonarchTable(doc)
    // Extract the monarchs and their reign dates
    monarchs := make(map[string]string)
    for _, row := range monarchTable.Child[1:] {
        name := ""
        startYear := 0
        endYear := 0
        for i, cell := range row.Child {
            switch i {
            case 0:
                name = strings.TrimSpace(extractText(cell))
            case 1:
                startYear, _ = strconv.Atoi(strings.TrimSpace(extractText(cell)))
            case 2:
                endYear, _ = strconv.Atoi(strings.TrimSpace(extractText(cell)))
            }
        }
        if name != "" && startYear >= 1500 && startYear < 1600 {
            monarchs[name] = fmt.Sprintf("%d-%d", startYear, endYear)
        }
    }
    // Print the monarchs
    fmt.Println("Monarchs of England during the 16th century:")
    for name, reign := range monarchs {
        fmt.Printf("%s: %s\n", name, reign)
    }
}
func findMonarchTable(n *html.Node) *html.Node {
    if n.Type == html.ElementNode && n.Data == "table" {
        for _, attr := range n.Attr {
            if attr.Key == "class" && strings.Contains(attr.Val, "wikitable") {
                return n
            }
        }
    }
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        if table := findMonarchTable(c); table != nil {
            return table
        }
    }
    return nil
}
func extractText(n *html.Node) string {
    if n.Type == html.TextNode {
        return n.Data
    }
    var text string
    for c := n.FirstChild; c != nil; c = c.NextSibling {
        text += extractText(c)
    }
    return text
}
```
This code makes a GET request to the URL of the HTML page, parses the HTML using the `html.Parse` function, and then traverses the HTML tree to find the table containing the monarchs. It then extracts the monarchs and their reign dates by iterating over the rows of the table and using the `extractText` function to extract the text from each cell. Finally, it prints the monarchs that reigned during the 16th century.

