import csv
import math
import time
def find_numbers(file_path):
    start_time = time.time()
    largest_divisible_by_3 = None
    smallest_prime = None
    with open(file_path, 'r') as f:
        reader = csv.reader(f)
        next(reader)  # skip header row
        for row in reader:
            for val in row:
                num = int(val)
                if num > 100 and num % 3 == 0:
                    if largest_divisible_by_3 is None or num > largest_divisible_by_3:
                        largest_divisible_by_3 = num
                if num < 50 and is_prime(num):
                    if smallest_prime is None or num < smallest_prime:
                        smallest_prime = num
    if largest_divisible_by_3 is None:
        print("No number in the table is divisible by 3 and greater than 100.")
    else:
        print("The largest number divisible by 3 and greater than 100 is:", largest_divisible_by_3)
    if smallest_prime is None:
        print("No prime number in the table is less than 50.")
    else:
        print("The smallest prime number less than 50 is:", smallest_prime)
    if largest_divisible_by_3 is not None and smallest_prime is not None:
        if largest_divisible_by_3 > smallest_prime:
            print("The largest number is greater than the smallest number.")
        elif smallest_prime > largest_divisible_by_3:
            print("The smallest number is greater than the largest number.")
        else:
            print("The two numbers are equal.")
    end_time = time.time()
    print("Execution time:", end_time - start_time, "seconds")
def is_prime(num):
    if num <= 1:
        return False
    elif num <= 3:
        return True
    elif num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True
```
